import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"思维","description":"","frontmatter":{},"headers":[],"relativePath":"idea/idea.md","filePath":"idea/idea.md","lastUpdated":null}'),l={name:"idea/idea.md"};function o(h,a,p,n,d,s){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="思维" tabindex="-1">思维 <a class="header-anchor" href="#思维" aria-label="Permalink to &quot;思维&quot;">​</a></h1><h2 id="规划思维应用职业规划" tabindex="-1">规划思维应用职业规划 <a class="header-anchor" href="#规划思维应用职业规划" aria-label="Permalink to &quot;规划思维应用职业规划&quot;">​</a></h2><p>小白需要实践的是如何通过自己的能力从资源生产者变成资源管理者，最后变成资源支配者。 <a href="http://www.woshipm.com/zhichang/4114367.html" target="_blank" rel="noreferrer">1</a></p><p>处于成长期阶段的人通过自己的技能输出得到回报，属于资源生产者； 处于领导者阶段的人除了技能输出，还是有整合资源的能力，属于资源管理者； 处于自我实现阶段产品经理通过参与创业的方式触碰行业天花板，属于资源支配者。</p><p>一个人属于哪个层面，与处在该层面的时间没有直接的联系，很多在一个行业做了N年的人，如果他们一直在成长期打转，在职业生涯中从来都没有支配过资源，那么就很难获得超额的价值回报。</p><p>其实有产品思维的牛人，不一定最开始是产品经理，比如王峰最开始的时候金山是负责营销工作，因为业绩出色，后来才成为了金山词霸和金山毒霸的产品市场负责人，最后做到金山副总裁。</p><p>在金山他跨越了成长期和领导者期，财务自由之后最后离职创业就很顺其自然，后面他成立了游戏公司上市，以及现在做的区块链媒体都属于自我实现阶段。</p><h2 id="逻辑思维来撕逼和思考" tabindex="-1">逻辑思维来撕逼和思考 <a class="header-anchor" href="#逻辑思维来撕逼和思考" aria-label="Permalink to &quot;逻辑思维来撕逼和思考&quot;">​</a></h2><p>逻辑思维能力被简单地理解为“任何一件事情都可以归纳出一个中心论点，而这个中心论点可以由3到7个论据进行支撑，每一个论据本身又可以成为一个论点。”</p><p>在逻辑思维中，由论据到论点的推理过程就叫作推理，推理是最根本的逻辑关系。</p><p>论点的成立与否是逻辑思维的主题，而论点的成立与否又直接源自论据的真假，如果论据是假的，那么得到的论点也是假的。</p><p>提升交流质量很重要一步就是用逻辑思考对方的观点是否正确，否者只能淹没在信息中。</p><p>还有的朋友在吵架撕逼的时候，用逻辑思维找出对方的论据错误和论据到论点的推理错误，往往能在撕逼中脱颖而出。</p><h2 id="敏捷思维对抗不确定性" tabindex="-1">敏捷思维对抗不确定性 <a class="header-anchor" href="#敏捷思维对抗不确定性" aria-label="Permalink to &quot;敏捷思维对抗不确定性&quot;">​</a></h2><p>有一次一个研发同学和我聊起买房的事情，他手里有些积蓄，想在杭州买一套大户型的房子，但是还差很多钱，于是他想着把钱攒够了在去买房。</p><p>但是我们知道杭州房价过去几年一直处于上升通道，用敏捷思维思考这个事情，我给他的建议是用自己手里的钱可以先买一个小户型的房子，有机会再换成大户型。</p><p>先解决从无到有，再去解决从小到大，如果继续等下去付出的成本只会越来越高。在面对重大不确定的重大选择时，最稳妥的方式就是用敏捷思维先解决核心需求。</p><p>利用敏捷思维要求每次只做最重要的事情，满足用户和环境不断的变化，并且努力把每一件小事情做好，期待未来回报奇点的到来。</p><p>身边大多数牛人拥有迭代思维还意味着他们很乐观，因为纵使对当前的产品不满意，但是他们会想各种办法，哪怕每天进步一点点，去不断迭代自己，而不是把时间浪费在对未知的恐惧。</p><h2 id="运营思维做销售" tabindex="-1">运营思维做销售 <a class="header-anchor" href="#运营思维做销售" aria-label="Permalink to &quot;运营思维做销售&quot;">​</a></h2><p>一个小米同学和我讲，在小米初创期间，黎万强一手打造了小米的社区模式，但是初期的阿黎在互联网圈中并不知名，小米初期也没有很强的品牌影响力。</p><p>所以阿黎只能组织团队，注册了很多小号，在各个论坛发布了很多MIUI的帖子，刚好用户也有需求，才慢慢积累的种子用户。</p><p>初期做法是不是和做微商有点类似？</p><h2 id="有限理性" tabindex="-1">有限理性 <a class="header-anchor" href="#有限理性" aria-label="Permalink to &quot;有限理性&quot;">​</a></h2><h3 id="原因" tabindex="-1">原因 <a class="header-anchor" href="#原因" aria-label="Permalink to &quot;原因&quot;">​</a></h3><ul><li>信息获取能力有限</li><li>信息处理能力有限</li><li>禀赋偏好导致的个体差异</li><li>环境的不确定因素</li></ul><h3 id="理性决策三要素" tabindex="-1">理性决策三要素 <a class="header-anchor" href="#理性决策三要素" aria-label="Permalink to &quot;理性决策三要素&quot;">​</a></h3><ul><li>理性的信念：与真实世界一致的信念，对自我认知的认知；人类最大的理性，就是理解自身认知能力的局限性</li><li>理性的目标：约束条件下的价值（总效用）最大化</li><li>理性的行动：给定目标下，寻找最优的解决方案</li></ul><h2 id="质疑" tabindex="-1">质疑 <a class="header-anchor" href="#质疑" aria-label="Permalink to &quot;质疑&quot;">​</a></h2><p>当你有一个想法的时候，你不要抱着它是对的去调研和分析，而是站在对立面，本着「这事情不靠谱」的思路，去做调研和分析。如果分析调研到最后，发现这个事情，真的确实可以，那么就是真的可以。<a href="https://www.zhihu.com/question/19638354/answer/377605037" target="_blank" rel="noreferrer">2</a></p>',30)])])}const _=e(l,[["render",o]]);export{u as __pageData,_ as default};
